const tg = window.Telegram?.WebApp;
if (tg) {
  tg.ready();
  tg.expand();
  // Apply Telegram colour scheme as data-theme so CSS :root[data-theme="dark"] selectors fire
  (function _applyTgTheme() {
    const scheme = tg.colorScheme;
    if (scheme === "dark" || scheme === "light") {
      document.documentElement.setAttribute("data-theme", scheme);
    }
    if (typeof tg.onEvent === "function") {
      tg.onEvent("themeChanged", () => {
        const s = tg.colorScheme;
        if (s === "dark" || s === "light") document.documentElement.setAttribute("data-theme", s);
      });
    }
  })();
  try {
    if (typeof tg.setHeaderColor === "function") tg.setHeaderColor("#ffd84d");
    if (typeof tg.setBackgroundColor === "function") tg.setBackgroundColor("#f6f7fb");
    if (typeof tg.requestFullscreen === "function") tg.requestFullscreen();
    else if (typeof tg.expand === "function") tg.expand();
    if (typeof tg.enableClosingConfirmation === "function") tg.enableClosingConfirmation();
  } catch (e) {
    console.warn("Telegram fullscreen request failed", e);
  }
}

// v7.0.8: set --tg-vh from Telegram viewportStableHeight so app-shell can use it as scroll container
function _updateTgViewportHeight() {
  const h = (tg && (tg.viewportStableHeight || tg.viewportHeight)) || window.innerHeight;
  if (h > 50) document.documentElement.style.setProperty("--tg-vh", h + "px");
}
_updateTgViewportHeight();
if (tg && typeof tg.onEvent === "function") {
  tg.onEvent("viewportChanged", _updateTgViewportHeight);
}
window.addEventListener("resize", _updateTgViewportHeight, { passive: true });

// v7.1.13.2 — mark body/html for Telegram CSS. --app-top-safe-offset
// starts from the CSS var chain (Telegram's own content-safe-area var when
// injected, else its plain safe-area var, else env()) — no hardcoded pixel
// guess — see the matching :root rule in styles.css. Set directly on
// <html> so it wins over any CSS body-class rule.
if (tg) {
  document.body.classList.add("is-telegram-webapp");
  document.documentElement.classList.add("is-telegram-webapp");
  document.documentElement.style.setProperty(
    "--app-top-safe-offset",
    "var(--tg-content-safe-area-inset-top, var(--tg-safe-area-inset-top, env(safe-area-inset-top, 0px)))"
  );
}

// v7.1.14.3 — real-device iPhone reports (and a Playwright render mocking
// Telegram iOS reporting contentSafeAreaInset.top=0/safeAreaInsets.top=0,
// which real Telegram iOS sessions are known to do) proved this offset can
// legitimately compute to 0px even though Telegram's own Close/Menu header
// row is physically still there covering that space — the previous code
// trusted a reported 0 completely. iosTelegramMinChromePx is a documented,
// GUARDED floor: only ever applied on tg.platform === "ios" (never Android/
// desktop/plain browser), only ever raises the value via Math.max (never
// added on top of it, so it can't double-stack with a correct larger real
// value), and only exists because the real WebView on iOS does not always
// return a usable inset. It is an estimate (iOS status bar up to ~59px on
// Dynamic Island devices + Telegram's own Close/Menu row ~44px, rounded up
// for the required 8px breathing room below them) pending confirmation
// against a real device — not a blind global guess like the old +56px,
// which applied to every platform unconditionally.
const IOS_TELEGRAM_MIN_TOP_SAFE_AREA_PX = 100;

// Refine with the WebApp JS API's own reported values when available —
// still real device/client data, never a fixed guess. Prefers
// contentSafeAreaInset (already includes Telegram's own header chrome,
// Bot API 8.0+) over the plainer safeAreaInsets (device notch only).
function _applySafeArea() {
  const content = tg?.contentSafeAreaInset || tg?.contentSafeAreaInsets;
  let px = null;
  if (content && typeof content.top === "number" && content.top >= 0) {
    px = content.top;
  } else {
    const top = tg?.safeAreaInsets?.top;
    if (typeof top === "number" && top >= 0) {
      // Device-notch-only value — Telegram's own chrome isn't included here,
      // so keep a small fixed breathing-room addition (not a guess at the
      // full chrome height like the old +56px was).
      document.documentElement.style.setProperty("--tg-safe-top", top + "px");
      px = top + 8;
    }
  }
  if (px === null) return; // no Telegram safe-area signal at all — leave the CSS env() fallback chain in control
  if (tg?.platform === "ios") {
    px = Math.max(px, IOS_TELEGRAM_MIN_TOP_SAFE_AREA_PX);
  }
  document.documentElement.style.setProperty("--app-top-safe-offset", px + "px");
}
_applySafeArea();
tg?.onEvent?.("safeAreaChanged", _applySafeArea);
// v7.1.14.2 — root cause of the "header runs under Telegram/iOS chrome"
// production regression: requestFullscreen() (above) is asynchronous, and
// Telegram only reports the real post-transition contentSafeAreaInset once
// it fires contentSafeAreaChanged/fullscreenChanged — neither of which was
// ever listened for here, only the unrelated safeAreaChanged (device notch
// changes). Without these, _applySafeArea's first run could apply a
// too-small value from before fullscreen finished settling, and nothing
// ever re-ran it afterward, on any role/screen (this shell/layout function
// is shared app-wide).
tg?.onEvent?.("contentSafeAreaChanged", _applySafeArea);
tg?.onEvent?.("fullscreenChanged", _applySafeArea);

// Prevent iOS/Telegram WebView zoom (pinch, gesture, double-tap)
["gesturestart", "gesturechange", "gestureend"].forEach(t =>
  document.addEventListener(t, e => e.preventDefault(), { passive: false })
);
let _lastTap = 0;
document.addEventListener("touchend", e => {
  const now = Date.now();
  if (now - _lastTap < 300) e.preventDefault();
  _lastTap = now;
}, { passive: false });

