// ═══════════════════════════════════════════════════════════════════════
// v7.1.17 — "Расписание" (continuing-students schedule foundation).
// Self-contained: own state object, own render/load functions (all
// prefixed _sched), own scoped CSS classes (.sched-*). Reuses the shared
// uiEmptyState/uiErrorState/uiConfirmSheet/uiStatusBadge/ws-skeleton
// primitives already used by other staff-workspace-style screens, but
// never reaches into Payments Workspace state. Feature-flagged end to
// end: the tab itself is hidden unless roleCaps().canUseScheduleFoundation
// (server-computed from SCHEDULE_FOUNDATION_ENABLED / pilot allowlist +
// real role) — see setupRoleUi(). Deleting this whole block plus its tab
// button/panel in index.html and its .sched-* CSS block removes the
// module cleanly; nothing else in the app reads _schedState.
// ═══════════════════════════════════════════════════════════════════════
const _schedState = {
  view: "overview",           // "overview" | "group-detail" | "draft-editor"
  tab: "overview",            // overview subtab
  status: null, statusLoading: false, statusError: null,
  stats: null, statsLoading: false,
  reqToken: 0,                // race-fencing, same capture-and-compare idiom as _wsPeriodState.reqToken
  pollTimer: null,

  groupsFilter: { branch: "", confidence: "", weekday: "", search: "" },
  groups: null, groupsTotal: 0, groupsLoading: false, groupsError: null,

  draftsFilter: { status: "", search: "" },
  drafts: null, draftsTotal: 0, draftsLoading: false, draftsError: null,

  membersFilter: { availability: "", continuation: "" },
  members: null, membersTotal: 0, membersLoading: false, membersError: null,

  currentGroupId: null, currentGroup: null, currentGroupLoading: false, currentGroupError: null,
  groupStudentFilter: { continuation: "", availability: "", search: "" },

  currentDraftId: null, currentDraft: null, currentDraftMembers: [], currentDraftConflicts: null,
  currentDraftAudit: [], currentDraftSourceGroup: null,
  currentDraftLoading: false, currentDraftError: null,
  editorDirty: false, editorPending: {}, editorSaving: false, editorVersionConflict: false,
  // ALE-10 member composition slice — "Добавить ребёнка" picker state,
  // separate from editorPending/editorDirty (member actions are their
  // own explicit, immediately-submitted actions, never batched with
  // unsaved field edits — see _schedMemberActionsBlockedByDirty).
  addPickerOpen: false, addCandidates: null, addCandidatesTotal: 0,
  addCandidatesLoading: false, addCandidatesError: null, addCandidatesRenderLimit: 30,
  addingMemberId: null,
  // Bug-fix (real-data E2E finding) — own generation counter, same
  // reasoning/convention as childrenReqGen below: the shared reqToken is
  // only bumped by the top-level _schedLoadStatus() loader, so it can't
  // fence two overlapping _schedLoadAddCandidates() calls against each
  // other (e.g. the picker is closed and reopened quickly while an older
  // multi-page fetch is still in flight).
  addCandidatesReqGen: 0,

  foundationGenerating: false,
  resyncTriggering: false,   // ALE-31 — disables the "Синхронизировать заново" control mid-request

  // ALE-10 — client_manager-facing "Дети" screen (draft-preview, human
  // language, read-only). Independent of groupsFilter/draftsFilter/etc.
  // above — never shares state with the older technical subtabs.
  // childrenReqGen/childrenDraftsReqGen — review-gate fix: the shared
  // reqToken above is only bumped by _schedLoadStatus() (top-level
  // "Расписание" tab entry), never by re-activating the "Дети" subtab —
  // so it can't fence two overlapping _schedLoadChildrenPlan() calls
  // against each other (e.g. the user leaves and quickly returns to the
  // subtab). These two counters are bumped at the start of their own
  // loader every call, so a call that's no longer the latest always
  // detects it and discards its result instead of clobbering newer state.
  childrenFilter: "all",
  children: null, childrenSummary: null, childrenLoading: false, childrenError: null, childrenRenderLimit: 50,
  childrenReqGen: 0,
  childrenDrafts: null, childrenDraftsLoading: false, childrenDraftsError: null, childrenDraftsReqGen: 0,
};

