const SCHED_ADD_CANDIDATE_GROUP_LABELS = {
  assignable: "Можно распределять", needs_review: "Нужно проверить",
  pending_confirmation: "Ждут подтверждения", stopped: "Не продолжают",
};
const SCHED_ADD_CANDIDATE_GROUP_ORDER = ["assignable", "needs_review", "pending_confirmation", "stopped"];

function _schedRenderChildrenPlan(root) {
  root.innerHTML = `
    <h3 class="sched-list-title" style="margin-top:0">Расписание нового учебного года</h3>
    <div id="schedChildrenSummary"></div>
    <div id="schedChildrenFilters"></div>
    <div id="schedChildrenListBody"></div>
    <h3 class="sched-list-title">Локальные черновики</h3>
    <div id="schedChildrenDraftsBody"></div>
  `;
  _schedRenderChildrenSummary();
  _schedRenderChildrenFilters();
  _schedRenderChildrenList();
  _schedRenderChildrenDrafts();
}

function _schedRenderChildrenSummary() {
  const el = $("schedChildrenSummary");
  if (!el) return;
  if (_schedState.childrenLoading && !_schedState.childrenSummary) { el.innerHTML = uiLoadingRows(2); return; }
  if (_schedState.childrenError) { el.innerHTML = ""; return; }
  const s = _schedState.childrenSummary || {};
  el.innerHTML = `<div class="sched-stat-grid">${SCHED_PREVIEW_SUMMARY_CARDS.map(([key, label]) => `
    <div class="sched-stat-card">
      <p class="sched-stat-card__value">${escapeHtml(String(s[key] ?? 0))}</p>
      <p class="sched-stat-card__label">${escapeHtml(label)}</p>
    </div>`).join("")}</div>`;
}

function _schedRenderChildrenFilters() {
  const el = $("schedChildrenFilters");
  if (!el) return;
  el.innerHTML = `<div class="sched-subtabs">${SCHED_PREVIEW_FILTERS.map(f => `
    <button class="sched-decision-filter${_schedState.childrenFilter === f.id ? " active" : ""}" onclick="_schedChildrenFilterChange('${f.id}')">${escapeHtml(f.label)}</button>
  `).join("")}</div>`;
  // Bugfix: assigning innerHTML resets the container's scrollLeft to 0
  // even though the active chip correctly moved — the horizontal filter
  // row visually snapped back to the start after every click. Bring the
  // active chip back into view, horizontally only ("nearest" on both
  // axes — the row is already vertically in place, so this never causes
  // a page-level vertical jump; "nearest" also means a chip that's
  // already visible is left alone, so rapid re-clicks don't fight the
  // user's own scroll position).
  const activeBtn = el.querySelector(".sched-decision-filter.active");
  if (activeBtn && typeof activeBtn.scrollIntoView === "function") {
    activeBtn.scrollIntoView({ block: "nearest", inline: "nearest" });
  }
}

function _schedChildrenFilterChange(filterId) {
  _schedState.childrenFilter = filterId;
  _schedState.childrenRenderLimit = 50;
  _schedRenderChildrenFilters();
  _schedRenderChildrenList();
}

// v7.1.18 — historical baseline is display-only context here, never a
// substitute for the backend decision badge (which is always rendered
// separately, unconditionally, from c.decision as-is).
//
// v7.1.19 bugfix — historical_group_name can already encode the day/time
// itself (real production names like "Воскресенье 17.00"), so appending
// the structured weekday/start_time unconditionally produced a visible
// duplicate ("Воскресенье 17.00 · воскресенье, 17:00"). Only append
// whichever of day/time isn't already present in the name — case-
// insensitive, tolerant of "17.00" vs "17:00" — never a hardcoded check
// for one specific day string, so any group-name convention is handled
// the same way.
function _schedChildBaselineText(c) {
  if (c.baseline_outcome === "found") {
    const name = c.historical_group_name || "Группа";
    const lowerName = name.toLowerCase();
    const dayName = SCHED_WEEKDAY_NAMES_FULL[c.historical_weekday] || "";
    const dayAlreadyInName = Boolean(dayName) && lowerName.includes(dayName.toLowerCase());
    const startTime = c.historical_start_time || "";
    const timeAlreadyInName = Boolean(startTime) && (lowerName.includes(startTime) || lowerName.includes(startTime.replace(":", ".")));
    const extra = [];
    if (dayName && !dayAlreadyInName) extra.push(dayName);
    if (startTime && !timeAlreadyInName) extra.push(startTime);
    return extra.length ? `${name} · ${extra.join(", ")}` : name;
  }
  if (c.baseline_outcome === "ambiguous") return "Несколько возможных групп";
  return "Основная группа не определена";
}

function _schedChildDecisionRowHtml(c) {
  return `
    <div class="sched-member-row">
      <div>
        ${_schedMemberNameHtml(c)}
        <p class="sched-member-row__tech">${escapeHtml(_schedChildBaselineText(c))}</p>
        <div class="sched-member-row__badges">
          ${uiStatusBadge(SCHED_CONTINUATION_LABELS[c.continuation_status] || c.continuation_status, SCHED_CONTINUATION_TONE[c.continuation_status] || "muted")}
          ${uiStatusBadge(SCHED_MATCH_LABELS[c.availability_match] || c.availability_match, SCHED_MATCH_TONE[c.availability_match] || "muted")}
          ${uiStatusBadge(SCHED_PREVIEW_DECISION_LABELS[c.decision] || c.decision, SCHED_PREVIEW_DECISION_TONE[c.decision] || "muted")}
        </div>
      </div>
    </div>`;
}

function _schedRenderChildrenList() {
  const el = $("schedChildrenListBody");
  if (!el) return;
  if (_schedState.childrenLoading && !_schedState.children) { el.innerHTML = uiLoadingRows(4); return; }
  if (_schedState.childrenError) { el.innerHTML = uiErrorState(_schedState.childrenError, "_schedLoadChildrenPlan()"); return; }
  const all = _schedState.children || [];
  const filter = _schedState.childrenFilter;
  const filtered = filter === "all" ? all : all.filter(c => c.decision === filter);
  if (!filtered.length) {
    el.innerHTML = uiEmptyState("👥", "Пока никого нет", "По выбранному фильтру детей не найдено.");
    return;
  }
  const limit = _schedState.childrenRenderLimit || 50;
  const visible = filtered.slice(0, limit);
  const hasMore = filtered.length > visible.length;
  el.innerHTML = `
    <p class="ws-results-count">Показано ${visible.length} из ${filtered.length}</p>
    <div class="sched-group-list">${visible.map(_schedChildDecisionRowHtml).join("")}</div>
    ${hasMore ? `<div class="sched-cta-row"><button class="secondary" onclick="_schedChildrenShowMore()">Показать ещё</button></div>` : ""}
  `;
}

function _schedChildrenShowMore() {
  _schedState.childrenRenderLimit = (_schedState.childrenRenderLimit || 50) + 50;
  _schedRenderChildrenList();
}

function _schedRenderChildrenDrafts() {
  const el = $("schedChildrenDraftsBody");
  if (!el) return;
  if (_schedState.childrenDraftsLoading && !_schedState.childrenDrafts) { el.innerHTML = uiLoadingRows(2); return; }
  if (_schedState.childrenDraftsError) { el.innerHTML = uiErrorState(_schedState.childrenDraftsError, "_schedLoadChildrenDrafts()"); return; }
  const drafts = _schedState.childrenDrafts || [];
  if (!drafts.length) {
    el.innerHTML = uiEmptyState(
      "🗂", "Черновиков пока нет",
      "Черновики появятся после того, как родители подтвердят продолжение обучения и укажут доступное время.",
    );
    return;
  }
  el.innerHTML = `<div class="sched-group-list">${drafts.map(dr => `
    <div class="sched-group-card">
      <div class="sched-group-card__header">
        <h3>${escapeHtml(dr.name || `Черновик #${dr.id}`)}</h3>
        ${uiStatusBadge(SCHED_DRAFT_STATUS_LABELS[dr.status] || dr.status, SCHED_DRAFT_STATUS_TONE[dr.status] || "muted")}
      </div>
      <p class="sched-group-card__meta">${escapeHtml(dr.course_name || "")} ${dr.branch_name ? "· " + escapeHtml(dr.branch_name) : ""} ${dr.teacher_name ? "· " + escapeHtml(dr.teacher_name) : ""}</p>
      <p class="sched-group-card__slot">${escapeHtml(_schedFmtSlot(dr))}</p>
      <p class="sched-group-card__stats"><span>Детей: ${dr.members_count ?? 0}</span></p>
      <div class="sched-group-card__actions">
        <button class="secondary" onclick="_schedOpenDraftEditor(${dr.id})">Открыть черновик</button>
      </div>
    </div>`).join("")}</div>`;
}

// Loops GET /api/schedule/draft-preview by offset until the server-
// reported total is reached (bounded by real data — hundreds, not
// thousands, of children per account) so client-side filtering by
// decision always operates on the complete set, never a stale first
// page. summary always reflects the FULL snapshot regardless of which
// page it came from (computed server-side before pagination), so it only
// needs to be read once.
//
// Review-gate fix: uses its OWN generation counter (childrenReqGen),
// bumped once per call to this function, rather than the shared
// _schedState.reqToken (which is only bumped by _schedLoadStatus() and
// never by re-activating this subtab) — two overlapping calls (user
// leaves and quickly returns to "Дети") are now correctly fenced: an
// older call detects it's no longer the latest after EVERY awaited page
// and bails out without touching state, so a slow stale response can
// never clobber a newer, already-applied result. _SCHED_CHILDREN_MAX_
// PAGES is defense-in-depth against an unexpected/malformed total that
// would otherwise never satisfy the loop's own exit condition — not
// expected to ever be hit with real data.
const _SCHED_CHILDREN_PAGE_LIMIT = 300;
const _SCHED_CHILDREN_MAX_PAGES = 50; // 50 * 300 = 15,000 children hard ceiling

async function _schedLoadChildrenPlan() {
  const myGen = ++_schedState.childrenReqGen;
  _schedState.childrenLoading = true;
  _schedState.childrenError = null;
  _schedState.childrenRenderLimit = 50;
  _schedRenderChildrenSummary();
  _schedRenderChildrenList();
  try {
    let offset = 0;
    let all = [];
    let summary = null;
    for (let page_i = 0; page_i < _SCHED_CHILDREN_MAX_PAGES; page_i++) {
      const d = await apiGet(`/api/schedule/draft-preview?limit=${_SCHED_CHILDREN_PAGE_LIMIT}&offset=${offset}`);
      if (myGen !== _schedState.childrenReqGen) return;
      if (!summary) summary = d.summary || null;
      const page = d.students || [];
      all = all.concat(page);
      const total = d.total || 0;
      offset += _SCHED_CHILDREN_PAGE_LIMIT;
      if (offset >= total || !page.length) break;
    }
    // Defensive de-dup by mk_user_id — a child must never appear twice in
    // the rendered list even if the underlying data shifted between two
    // page fetches (rare, but the filters/summary math must still hold).
    const seen = new Set();
    const deduped = [];
    for (const c of all) {
      if (seen.has(c.mk_user_id)) continue;
      seen.add(c.mk_user_id);
      deduped.push(c);
    }
    _schedState.children = deduped;
    _schedState.childrenSummary = summary || { total: deduped.length };
    _schedState.childrenLoading = false;
    _schedRenderChildrenSummary();
    _schedRenderChildrenList();
  } catch (e) {
    if (myGen !== _schedState.childrenReqGen) return;
    _schedState.childrenLoading = false;
    _schedState.childrenError = e.message || String(e);
    _schedRenderChildrenSummary();
    _schedRenderChildrenList();
  }
}

// Same offset-loop + own-generation-counter pattern as _schedLoadChildrenPlan
// above, applied to GET /api/schedule/drafts (server cap: 200/page). Real
// persisted-draft count is bounded by the number of historical groups
// (~130 in the real account per the ALE-6 audit), which already exceeded
// this function's old single-page limit=100 — a single page was never
// safe here either. Currently always empty in production (draft
// generation is still off), but must not silently truncate once it isn't.
const _SCHED_DRAFTS_PAGE_LIMIT = 200;
const _SCHED_DRAFTS_MAX_PAGES = 50;

async function _schedLoadChildrenDrafts() {
  const myGen = ++_schedState.childrenDraftsReqGen;
  _schedState.childrenDraftsLoading = true;
  _schedState.childrenDraftsError = null;
  try {
    let offset = 0;
    let all = [];
    for (let page_i = 0; page_i < _SCHED_DRAFTS_MAX_PAGES; page_i++) {
      const d = await apiGet(`/api/schedule/drafts?limit=${_SCHED_DRAFTS_PAGE_LIMIT}&offset=${offset}`);
      if (myGen !== _schedState.childrenDraftsReqGen) return;
      const page = d.drafts || [];
      all = all.concat(page);
      const total = d.total || 0;
      offset += _SCHED_DRAFTS_PAGE_LIMIT;
      if (offset >= total || !page.length) break;
    }
    const seen = new Set();
    const deduped = [];
    for (const d of all) {
      if (seen.has(d.id)) continue;
      seen.add(d.id);
      deduped.push(d);
    }
    _schedState.childrenDrafts = deduped;
    _schedState.childrenDraftsLoading = false;
    _schedRenderChildrenDrafts();
  } catch (e) {
    if (myGen !== _schedState.childrenDraftsReqGen) return;
    _schedState.childrenDraftsLoading = false;
    _schedState.childrenDraftsError = e.message || String(e);
    _schedRenderChildrenDrafts();
  }
}

// ── Status + overview ────────────────────────────────────────────────
async function _schedLoadStatus() {
  _schedState.statusLoading = true;
  _schedState.statusError = null;
  const myToken = ++_schedState.reqToken;
  try {
    const d = await apiGet("/api/schedule/status");
    if (myToken !== _schedState.reqToken) return;
    _schedState.status = d;
    _schedState.statusLoading = false;
    _schedRenderSyncStatusLine();
    _schedRenderCurrentTab();
    if (d.runningSnapshot) _schedStartPolling(d.runningSnapshot.id);
    else _schedStopPolling();
    if (d.activeSnapshot) _schedLoadStats();
  } catch (e) {
    if (myToken !== _schedState.reqToken) return;
    _schedState.statusLoading = false;
    _schedState.statusError = e.message || String(e);
    _schedRenderCurrentTab();
  }
}

async function _schedLoadStats() {
  const myToken = _schedState.reqToken;
  _schedState.statsLoading = true;
  try {
    const d = await apiGet("/api/schedule/stats");
    if (myToken !== _schedState.reqToken) return;
    _schedState.stats = d.stats;
    _schedState.statsLoading = false;
    if (_schedState.tab === "overview") _schedRenderCurrentTab();
  } catch (e) {
    if (myToken !== _schedState.reqToken) return;
    _schedState.statsLoading = false;
  }
}

function _schedRenderSyncStatusLine() {
  const el = $("schedSyncStatusLine");
  if (!el || !_schedState.status) return;
  const s = _schedState.status;
  const active = s.activeSnapshot;
  if (s.runningSnapshot) {
    el.innerHTML = `<span class="sched-sync-badge sched-sync-badge--running">Синхронизация выполняется…</span>`;
  } else if (active) {
    // ALE-31 — the only way to reach this branch is a completed active
    // snapshot with no sync currently running; still check active.status
    // explicitly rather than relying on that invariant implicitly.
    // A newer failed/partial attempt (same condition _schedRenderOverview
    // uses for its "Повторить" retry banner) must own that recovery flow
    // exclusively — the fresh-resync control here is for the healthy
    // state only, never shown alongside the retry banner.
    const latest = (s.recentSnapshots && s.recentSnapshots[0]) || null;
    const hasUnresolvedFailedAttempt = !!(latest && latest.id !== active.id && (latest.status === "failed" || latest.status === "partial"));
    const canResync = active.status === "completed" && s.syncEnabled && !hasUnresolvedFailedAttempt;
    el.innerHTML = `<span class="sched-sync-badge">Последняя синхронизация: ${escapeHtml(_schedFmtDate(active.completed_at))}</span>` +
      (canResync
        ? `<button class="sched-linklike" ${_schedState.resyncTriggering ? "disabled" : ""} onclick="_schedTriggerResync()">${_schedState.resyncTriggering ? "Запускаем…" : "Синхронизировать заново"}</button>`
        : "");
  } else {
    el.innerHTML = `<span class="sched-sync-badge sched-sync-badge--muted">Синхронизация ещё не выполнялась</span>`;
  }
}

// ALE-31 — minimal resync control for the healthy-active-snapshot state,
// where the pre-existing first-sync/retry buttons never render (both are
// gated on activeSnapshot being absent or the latest attempt having
// failed/partial status). Reuses _schedStartSync() with no
// resume_snapshot_id, so it always creates a brand-new snapshot — same
// path as a first sync, never touches the existing active snapshot.
//
// The whole body (including the first render call) is inside try/finally
// so resyncTriggering is guaranteed to return to false even if that first
// render throws — _schedStartSync() itself never rejects (it catches its
// own errors internally), but the render call is not similarly guarded on
// its own, so it must share the same try/finally rather than run before it.
async function _schedTriggerResync() {
  if (_schedState.resyncTriggering) return;
  if (_schedState.status && _schedState.status.runningSnapshot) return;
  _schedState.resyncTriggering = true;
  try {
    _schedRenderSyncStatusLine();
    await _schedStartSync();
  } finally {
    _schedState.resyncTriggering = false;
    _schedRenderSyncStatusLine();
  }
}

function _schedStartPolling(snapshotId) {
  _schedStopPolling();
  _schedState.pollTimer = setInterval(() => _schedPollProgress(snapshotId), 2500);
  _schedPollProgress(snapshotId);
}

async function _schedPollProgress(snapshotId) {
  if (_schedState.tab !== "overview" && _schedState.view === "overview") { /* still poll, just render on overview */ }
  try {
    const d = await apiGet(`/api/schedule/sync/progress?snapshot_id=${encodeURIComponent(snapshotId)}`);
    _schedState.status = _schedState.status || {};
    if (d.snapshot.status === "running") {
      _schedState.status.runningSnapshot = d.snapshot;
      _schedState.statusStageLabel = d.stageLabel;
      _schedState.statusErrors = d.errors;
      if (_schedState.tab === "overview" && _schedState.view === "overview") _schedRenderCurrentTab();
    } else {
      _schedStopPolling();
      _schedState.status.runningSnapshot = null;
      await _schedLoadStatus();
    }
  } catch (e) {
    _schedStopPolling();
  }
}

function _schedRenderOverview(root) {
  const s = _schedState.status;
  if (_schedState.statusLoading && !s) { root.innerHTML = uiLoadingRows(4); return; }
  if (_schedState.statusError) {
    root.innerHTML = uiErrorState(`Не удалось загрузить раздел: ${escapeHtml(_schedState.statusError)}`, "_schedLoadStatus()");
    return;
  }
  if (!s || !s.ok) {
    root.innerHTML = uiErrorState((s && s.error) || "Раздел недоступен.", "_schedLoadStatus()");
    return;
  }

  // Sync running — progress view
  if (s.runningSnapshot) {
    root.innerHTML = _schedSyncProgressHtml(s.runningSnapshot, _schedState.statusStageLabel, _schedState.statusErrors);
    return;
  }

  // No snapshot at all yet
  if (!s.activeSnapshot && (!s.recentSnapshots || !s.recentSnapshots.length)) {
    const canSync = s.syncEnabled;
    root.innerHTML = uiEmptyState(
      "🗓", "Синхронизация ещё не выполнялась",
      canSync
        ? "Запустите синхронизацию, чтобы получить прошлогодние группы и занятия из МойКласс (только чтение)."
        : "Синхронизация с МойКласс сейчас выключена настройками.",
    ) + (canSync ? `<div class="sched-cta-row"><button class="primary" onclick="_schedStartSync()">Начать синхронизацию</button></div>` : "");
    return;
  }

  // Latest attempt failed/partial and there's no usable active snapshot
  const latest = (s.recentSnapshots && s.recentSnapshots[0]) || null;
  if (!s.activeSnapshot && latest && (latest.status === "failed" || latest.status === "partial")) {
    root.innerHTML = uiErrorState(
      !s.moyklassConfigured
        ? "МойКласс недоступен: не настроен API-ключ."
        : "Последняя синхронизация завершилась с ошибкой, годного snapshot ещё нет.",
      latest.resumable ? `_schedStartSync(${latest.id})` : "_schedStartSync()",
    );
    return;
  }

  const active = s.activeSnapshot;
  const stats = _schedState.stats;
  let html = "";

  if (latest && latest.id !== active.id && (latest.status === "failed" || latest.status === "partial")) {
    html += `<div class="sched-warning-banner">Последняя попытка синхронизации (${escapeHtml(_schedFmtDate(latest.started_at))}) завершилась с ошибками и не была применена — используются данные предыдущей успешной синхронизации.
      ${latest.resumable ? `<button class="sched-linklike" onclick="_schedStartSync(${latest.id})">Повторить</button>` : ""}</div>`;
  }

  if (!stats) {
    html += uiLoadingRows(3);
  } else if (stats.groups_count === 0) {
    html += uiEmptyState("📭", "Группы не найдены", "Синхронизация завершилась успешно, но подходящих групп за указанный период не найдено.");
  } else {
    html += _schedDataQualityHtml(stats);
    html += _schedStatGridHtml(stats);
    if (stats.drafts_count === 0 && s.mutationsEnabled) {
      html += `<div class="sched-cta-row"><button class="primary" ${_schedState.foundationGenerating ? "disabled" : ""} onclick="_schedConfirmGenerateFoundation()">${_schedState.foundationGenerating ? "Создаём…" : "Создать основу из прошлого года"}</button></div>`;
    } else if (stats.drafts_count === 0 && !s.mutationsEnabled) {
      html += uiInlineNotice("Редактирование черновиков выключено настройками — данные доступны только для просмотра.", "info");
    }
  }
  root.innerHTML = html;
}

// v7.1.17.1 — ALE-6 section 8 Data Quality block. The whole point is to
// make it impossible to read "raw_unique_student_ids_count" as if it were
// the regular-student roster — regular_confirmed/regular_inferred_high are
// the only categories a future auto-generated draft could ever use, and
// even that is still fully disabled in this release (SCHEDULE_FOUNDATION_
// ENABLED / SCHEDULE_DRAFT_MUTATIONS_ENABLED stay off).
function _schedDataQualityHtml(st) {
  const raw = st.raw_unique_student_ids_count ?? st.students_count ?? 0;
  const confirmed = st.regular_confirmed_count || 0;
  const high = st.regular_inferred_high_count || 0;
  const medium = st.regular_inferred_medium_count || 0;
  const excluded = st.excluded_irregular_count || 0;
  const insufficient = st.insufficient_evidence_count || 0;
  const ambiguous = st.ambiguous_regularity_count || 0;
  const rows = [
    ["regular_confirmed", "Постоянные (подтверждено)", confirmed, "success"],
    ["regular_inferred_high", "Постоянные (вероятно)", high, "success"],
    ["regular_inferred_medium", "Возможно постоянные", medium, "warning"],
    ["excluded_irregular", "Исключены (пробные/отработки/разовые/гости)", excluded, "muted"],
    ["insufficient_evidence", "Недостаточно данных", insufficient, "muted"],
    ["ambiguous", "Неоднозначно — нужна проверка", ambiguous, "danger"],
  ];
  const contDetail = st.continuation_detail_breakdown || {};
  const availDetail = st.availability_detail_breakdown || {};
  const contRows = [
    ["continues", "Продолжают", contDetail.continues || 0],
    ["discontinued", "Прекратили", contDetail.discontinued || 0],
    ["awaiting_confirmation", "Ожидают подтверждения", contDetail.awaiting_confirmation || 0],
    ["status_not_found", "Нет записи об onboarding", contDetail.status_not_found || 0],
    ["ambiguous_multiple_records", "Противоречивые записи", contDetail.ambiguous_multiple_records || 0],
  ];
  const availRows = [
    ["filled", "Заполнили возможности", availDetail.filled || 0],
    ["invited_not_filled", "Подключены, но не заполнили", availDetail.invited_not_filled || 0],
    ["parent_not_connected", "Родитель не подключён", availDetail.parent_not_connected || 0],
    ["no_onboarding_record", "Нет записи об onboarding", availDetail.no_onboarding_record || 0],
    ["ambiguous", "Неоднозначно", availDetail.ambiguous || 0],
  ];
  return `
    <div class="sched-quality-block">
      <p class="sched-quality-block__title">Качество данных</p>
      <p class="sched-quality-block__note">Всего уникальных ID в источнике: <b>${escapeHtml(String(raw))}</b> — это НЕ значит «${escapeHtml(String(raw))} постоянных учеников». Ниже — фактическая классификация.</p>
      <table class="sched-quality-table">
        <tbody>
          ${rows.map(([key, label, value, tone]) => `
            <tr>
              <td class="sched-quality-table__label">${escapeHtml(label)}</td>
              <td class="sched-quality-table__value">${uiStatusBadge(String(value), tone)}</td>
            </tr>`).join("")}
        </tbody>
      </table>
      <p class="sched-quality-block__subtitle">Продолжение обучения</p>
      <table class="sched-quality-table">
        <tbody>
          ${contRows.map(([key, label, value]) => `
            <tr><td class="sched-quality-table__label">${escapeHtml(label)}</td><td class="sched-quality-table__value">${escapeHtml(String(value))}</td></tr>`).join("")}
        </tbody>
      </table>
      <p class="sched-quality-block__subtitle">Возможности (Availability)</p>
      <table class="sched-quality-table">
        <tbody>
          ${availRows.map(([key, label, value]) => `
            <tr><td class="sched-quality-table__label">${escapeHtml(label)}</td><td class="sched-quality-table__value">${escapeHtml(String(value))}</td></tr>`).join("")}
        </tbody>
      </table>
      ${st.sync_errors_count ? `<p class="sched-quality-block__errors">Ошибок синхронизации: ${escapeHtml(String(st.sync_errors_count))}</p>` : ""}
    </div>`;
}

function _schedStatGridHtml(st) {
  const cards = [
    ["Групп прошлого года", st.groups_count],
    ["Детей в источнике (raw)", st.raw_unique_student_ids_count ?? st.students_count],
    ["Продолжают обучение", st.continues_count],
    ["Продолжение не подтверждено", st.unconfirmed_count],
    ["Прекратили обучение", st.discontinued_count],
    ["Заполнили возможности", st.filled_availability_count],
    ["Не заполнили возможности", st.not_filled_availability_count],
    ["Прежний слот подходит", st.preferred_or_possible_match_count],
    ["Возможны с оговорками", st.possible_with_caveats_count],
    ["Конфликты", st.conflict_count],
    ["Неоднозначные данные", st.ambiguous_confidence_groups_count],
    ["Локальные черновики", st.drafts_count],
    ["Готовы к проверке", st.drafts_ready_count],
  ];
  return `<div class="sched-stat-grid">${cards.map(([label, value]) => `
    <div class="sched-stat-card">
      <p class="sched-stat-card__value">${escapeHtml(String(value ?? 0))}</p>
      <p class="sched-stat-card__label">${escapeHtml(label)}</p>
    </div>`).join("")}</div>`;
}

function _schedSyncProgressHtml(snap, stageLabel, errors) {
  const label = stageLabel || SCHED_STAGE_LABELS[snap.stage] || snap.stage || "Выполняется";
  return `
    <div class="sched-sync-progress">
      <p class="sched-sync-progress__stage">${escapeHtml(label)}…</p>
      <div class="sched-sync-counters">
        <div><span>${snap.groups_found || 0}</span><label>групп найдено</label></div>
        <div><span>${snap.groups_processed || 0}</span><label>групп обработано</label></div>
        <div><span>${snap.lessons_fetched || 0}</span><label>занятий загружено</label></div>
        <div><span>${snap.students_found || 0}</span><label>учеников найдено</label></div>
        <div><span>${snap.errors_count || 0}</span><label>ошибок</label></div>
      </div>
      <p class="sched-sync-progress__meta">Начало: ${escapeHtml(_schedFmtDate(snap.started_at))} · последняя активность: ${escapeHtml(_schedFmtDate(snap.last_activity_at))}</p>
      ${errors && errors.length ? `<div class="sched-sync-errors">${errors.slice(0, 5).map(er => `<p>${escapeHtml(er.message || er.error_code || "")}</p>`).join("")}</div>` : ""}
    </div>`;
}

async function _schedStartSync(resumeSnapshotId) {
  if (_schedState.status && _schedState.status.runningSnapshot) return;
  try {
    const d = await apiPost("/api/schedule/sync/start", resumeSnapshotId ? { resume_snapshot_id: resumeSnapshotId } : {});
    await _schedLoadStatus();
    if (d.snapshot) _schedStartPolling(d.snapshot.id);
  } catch (e) {
    setNotice(`Не удалось запустить синхронизацию: ${e.message}`, "error");
  }
}

function _schedConfirmGenerateFoundation() {
  const stats = _schedState.stats || {};
  uiConfirmSheet({
    scopeClass: "sched-scope",
    title: "Создать основу из прошлого года",
    message: `Будет обработано групп: ${stats.groups_count || 0}, детей: ${stats.students_count || 0}.\nВ МойКласс ничего не будет записано.\nУведомления клиентам не отправляются.\nПовторное нажатие не создаст дубли — уже существующие черновики останутся без изменений.`,
    confirmLabel: "Создать основу",
    onConfirm: async () => {
      _schedState.foundationGenerating = true;
      try {
        await apiPost("/api/schedule/foundation/generate", {});
        _schedState.foundationGenerating = false;
        await _schedLoadStats();
        _schedRenderCurrentTab();
        setNotice("Основа расписания создана.", "success");
      } catch (e) {
        _schedState.foundationGenerating = false;
        setNotice(`Не удалось создать основу: ${e.message}`, "error");
      }
    },
  });
}

// ── Groups list ──────────────────────────────────────────────────────
function _schedRenderGroupsList(root) {
  const f = _schedState.groupsFilter;
  root.innerHTML = `
    <div class="sched-filter-bar">
      <input type="text" class="sched-search-input" placeholder="Поиск по названию группы" value="${escapeHtml(f.search)}" oninput="_schedGroupsFilterChange('search', this.value)" />
      <select onchange="_schedGroupsFilterChange('confidence', this.value)">
        <option value="">Уверенность: все</option>
        <option value="high" ${f.confidence === "high" ? "selected" : ""}>Высокая</option>
        <option value="medium" ${f.confidence === "medium" ? "selected" : ""}>Средняя</option>
        <option value="low" ${f.confidence === "low" ? "selected" : ""}>Низкая</option>
        <option value="ambiguous" ${f.confidence === "ambiguous" ? "selected" : ""}>Неоднозначно</option>
      </select>
      <select onchange="_schedGroupsFilterChange('weekday', this.value)">
        <option value="">День: все</option>
        ${Object.entries(SCHED_WEEKDAY_NAMES_FULL).map(([n, name]) => `<option value="${n}" ${String(f.weekday) === n ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}
      </select>
    </div>
    <div id="schedGroupsListBody"></div>
  `;
  _schedRenderGroupsListBody();
}

function _schedGroupsFilterChange(key, value) {
  _schedState.groupsFilter[key] = value;
  _schedLoadGroups();
}

function _schedRenderGroupsListBody() {
  const el = $("schedGroupsListBody");
  if (!el) return;
  if (_schedState.groupsLoading && !_schedState.groups) { el.innerHTML = uiLoadingRows(4); return; }
  if (_schedState.groupsError) { el.innerHTML = uiErrorState(_schedState.groupsError, "_schedLoadGroups()"); return; }
  const groups = _schedState.groups || [];
  if (!groups.length) { el.innerHTML = uiEmptyState("📭", "Группы не найдены", "Измените фильтры или запустите синхронизацию."); return; }
  el.innerHTML = `<div class="sched-group-list">${groups.map(_schedGroupCardHtml).join("")}</div>`;
}

function _schedGroupCardHtml(g) {
  const tone = SCHED_CONFIDENCE_TONE[g.confidence] || "muted";
  return `
    <div class="sched-group-card">
      <div class="sched-group-card__header">
        <h3>${escapeHtml(g.name || `Группа ${g.mk_class_id}`)}</h3>
        ${uiStatusBadge(SCHED_CONFIDENCE_LABELS[g.confidence] || g.confidence, tone)}
      </div>
      <p class="sched-group-card__meta">${escapeHtml(g.course_name || "")} ${g.branch_name ? "· " + escapeHtml(g.branch_name) : ""} ${g.teacher_name ? "· " + escapeHtml(g.teacher_name) : ""}</p>
      <p class="sched-group-card__slot">${escapeHtml(_schedFmtSlot(g))}</p>
      <p class="sched-group-card__reason">${escapeHtml(g.confidence_reason || "")}</p>
      <div class="sched-group-card__stats">
        <span>Занятий: ${g.lessons_count || 0}</span>
        <span>Детей: ${g.students_count || 0}</span>
        <span>${escapeHtml(_schedFmtDate(g.first_lesson_date))} — ${escapeHtml(_schedFmtDate(g.last_lesson_date))}</span>
      </div>
      <div class="sched-group-card__actions">
        <button class="secondary" onclick="_schedOpenGroupDetail(${g.id})">Открыть группу</button>
      </div>
      <p class="sched-group-card__tech">ID МойКласс: ${escapeHtml(g.mk_class_id)}</p>
    </div>`;
}

async function _schedLoadGroups() {
  const el = $("schedGroupsListBody");
  _schedState.groupsLoading = true;
  _schedState.groupsError = null;
  if (el) _schedRenderGroupsListBody();
  const myToken = _schedState.reqToken;
  const f = _schedState.groupsFilter;
  const qp = new URLSearchParams();
  if (f.branch) qp.set("branch", f.branch);
  if (f.confidence) qp.set("confidence", f.confidence);
  if (f.weekday) qp.set("weekday", f.weekday);
  if (f.search) qp.set("search", f.search);
  qp.set("limit", "100");
  try {
    const d = await apiGet(`/api/schedule/groups?${qp.toString()}`);
    if (myToken !== _schedState.reqToken) return;
    _schedState.groups = d.groups || [];
    _schedState.groupsTotal = d.total || 0;
    _schedState.groupsLoading = false;
    _schedRenderGroupsListBody();
  } catch (e) {
    if (myToken !== _schedState.reqToken) return;
    _schedState.groupsLoading = false;
    _schedState.groupsError = e.message || String(e);
    _schedRenderGroupsListBody();
  }
}

// ── Group detail ─────────────────────────────────────────────────────
function _schedOpenGroupDetail(groupId) {
  _schedState.view = "group-detail";
  _schedState.currentGroupId = groupId;
  _schedState.currentGroup = null;
  _schedState.groupStudentFilter = { continuation: "", availability: "", search: "" };
  _schedSetBackButton();
  const root = $("scheduleFoundationRoot");
  root.innerHTML = `<div id="schedGroupDetailRoot">${uiLoadingRows(4)}</div>`;
  _schedLoadGroupDetail(groupId);
}

async function _schedLoadGroupDetail(groupId) {
  _schedState.currentGroupLoading = true;
  _schedState.currentGroupError = null;
  const myToken = _schedState.reqToken;
  const f = _schedState.groupStudentFilter;
  const qp = new URLSearchParams();
  if (f.continuation) qp.set("continuation", f.continuation);
  if (f.availability) qp.set("availability", f.availability);
  if (f.search) qp.set("search", f.search);
  try {
    const d = await apiGet(`/api/schedule/groups/${groupId}?${qp.toString()}`);
    if (myToken !== _schedState.reqToken) return;
    _schedState.currentGroup = d;
    _schedState.currentGroupLoading = false;
    _schedRenderGroupDetail();
  } catch (e) {
    if (myToken !== _schedState.reqToken) return;
    _schedState.currentGroupLoading = false;
    _schedState.currentGroupError = e.message || String(e);
    _schedRenderGroupDetail();
  }
}

function _schedRenderGroupDetail() {
  const root = $("schedGroupDetailRoot");
  if (!root) return;
  if (_schedState.currentGroupLoading && !_schedState.currentGroup) { root.innerHTML = uiLoadingRows(4); return; }
  if (_schedState.currentGroupError) { root.innerHTML = uiErrorState(_schedState.currentGroupError, `_schedLoadGroupDetail(${_schedState.currentGroupId})`); return; }
  const d = _schedState.currentGroup;
  if (!d || !d.ok) { root.innerHTML = uiErrorState((d && d.error) || "Группа не найдена.", null); return; }
  const g = d.group;
  const f = _schedState.groupStudentFilter;
  root.innerHTML = `
    <div class="sched-detail-header">
      <button class="sched-linklike" onclick="_schedGoToOverview()">← К группам</button>
      <h2>${escapeHtml(g.name || `Группа ${g.mk_class_id}`)}</h2>
      <p class="sched-group-card__meta">${escapeHtml(g.course_name || "")} ${g.branch_name ? "· " + escapeHtml(g.branch_name) : ""} ${g.teacher_name ? "· " + escapeHtml(g.teacher_name) : ""}</p>
      <p class="sched-group-card__slot">${escapeHtml(_schedFmtSlot(g))} ${uiStatusBadge(SCHED_CONFIDENCE_LABELS[g.confidence] || g.confidence, SCHED_CONFIDENCE_TONE[g.confidence] || "muted")}</p>
      <p class="sched-group-card__reason">${escapeHtml(g.confidence_reason || "")}</p>
      <p class="sched-group-card__tech">ID МойКласс: ${escapeHtml(g.mk_class_id)}${g.is_closed ? " · группа отсутствует в текущем списке МойКласс" : ""}</p>
      ${d.linkedDraft ? `<div class="sched-cta-row"><button class="secondary" onclick="_schedOpenDraftEditor(${d.linkedDraft.id})">Открыть черновик</button></div>` : ""}
    </div>
    <div class="sched-filter-bar">
      <input type="text" class="sched-search-input" placeholder="Поиск ребёнка" value="${escapeHtml(f.search)}" oninput="_schedGroupStudentFilterChange('search', this.value)" />
      <select onchange="_schedGroupStudentFilterChange('continuation', this.value)">
        <option value="">Продолжение: все</option>
        ${Object.entries(SCHED_CONTINUATION_LABELS).map(([k, l]) => `<option value="${k}" ${f.continuation === k ? "selected" : ""}>${escapeHtml(l)}</option>`).join("")}
      </select>
      <select onchange="_schedGroupStudentFilterChange('availability', this.value)">
        <option value="">Возможности: все</option>
        ${Object.entries(SCHED_MATCH_LABELS).map(([k, l]) => `<option value="${k}" ${f.availability === k ? "selected" : ""}>${escapeHtml(l)}</option>`).join("")}
      </select>
    </div>
    <div class="sched-student-list">
      ${d.students.length ? d.students.map(s => `
        <div class="sched-member-row">
          <div>
            ${_schedMemberNameHtml(s)}
            <p class="sched-member-row__tech">регулярных занятий: ${s.lessons_attended || 0}${s.n_trial_visits ? ` · пробных: ${s.n_trial_visits}` : ""}${s.n_makeup_visits ? ` · отработок: ${s.n_makeup_visits}` : ""}${s.is_current_group === 0 ? " · прошлая группа" : ""}</p>
          </div>
          <div class="sched-member-row__badges">
            ${s.regularity_category ? uiStatusBadge(SCHED_REGULARITY_LABELS[s.regularity_category] || s.regularity_category, SCHED_REGULARITY_TONE[s.regularity_category] || "muted") : ""}
            ${uiStatusBadge(SCHED_CONTINUATION_LABELS[s.continuation_status] || s.continuation_status, SCHED_CONTINUATION_TONE[s.continuation_status] || "muted")}
            ${uiStatusBadge(SCHED_MATCH_LABELS[s.availability_match] || s.availability_match, SCHED_MATCH_TONE[s.availability_match] || "muted")}
          </div>
        </div>`).join("") : uiEmptyState("👥", "Нет учеников", "По выбранным фильтрам ученики не найдены.")}
    </div>
  `;
}

function _schedGroupStudentFilterChange(key, value) {
  _schedState.groupStudentFilter[key] = value;
  _schedLoadGroupDetail(_schedState.currentGroupId);
}

// ── Drafts list ("Основа расписания" / "Требуют решения" / "Черновики") ─
function _schedRenderDraftsList(root, mode) {
  const titles = { ready: "Основа расписания (готово к проверке)", "needs-review": "Требуют решения", all: "Черновики" };
  root.innerHTML = `<p class="sched-list-title">${escapeHtml(titles[mode] || "")}</p><div id="schedDraftsListBody"></div>`;
  _schedRenderDraftsListBody(mode);
}

function _schedRenderDraftsListBody(mode) {
  const el = $("schedDraftsListBody");
  if (!el) return;
  if (_schedState.draftsLoading && !_schedState.drafts) { el.innerHTML = uiLoadingRows(3); return; }
  if (_schedState.draftsError) { el.innerHTML = uiErrorState(_schedState.draftsError, `_schedLoadDrafts('${mode}')`); return; }
  const drafts = _schedState.drafts || [];
  if (!drafts.length) { el.innerHTML = uiEmptyState("🗂", "Черновиков нет", "Черновики появятся после создания основы из прошлого года."); return; }
  el.innerHTML = `<div class="sched-group-list">${drafts.map(dr => `
    <div class="sched-group-card">
      <div class="sched-group-card__header">
        <h3>${escapeHtml(dr.name || `Черновик #${dr.id}`)}</h3>
        ${uiStatusBadge(SCHED_DRAFT_STATUS_LABELS[dr.status] || dr.status, SCHED_DRAFT_STATUS_TONE[dr.status] || "muted")}
      </div>
      <p class="sched-group-card__meta">${escapeHtml(dr.course_name || "")} ${dr.branch_name ? "· " + escapeHtml(dr.branch_name) : ""} ${dr.teacher_name ? "· " + escapeHtml(dr.teacher_name) : ""}</p>
      <p class="sched-group-card__slot">${escapeHtml(_schedFmtSlot(dr))}</p>
      <div class="sched-group-card__actions">
        <button class="secondary" onclick="_schedOpenDraftEditor(${dr.id})">Открыть черновик</button>
      </div>
    </div>`).join("")}</div>`;
}

async function _schedLoadDrafts(mode) {
  _schedState.draftsLoading = true;
  _schedState.draftsError = null;
  const myToken = _schedState.reqToken;
  const qp = new URLSearchParams({ limit: "100" });
  if (mode === "ready") qp.set("status", "ready");
  if (mode === "needs-review") qp.set("status", "needs_review");
  try {
    const d = await apiGet(`/api/schedule/drafts?${qp.toString()}`);
    if (myToken !== _schedState.reqToken) return;
    _schedState.drafts = d.drafts || [];
    _schedState.draftsTotal = d.total || 0;
    _schedState.draftsLoading = false;
    _schedRenderDraftsListBody(mode);
  } catch (e) {
    if (myToken !== _schedState.reqToken) return;
    _schedState.draftsLoading = false;
    _schedState.draftsError = e.message || String(e);
    _schedRenderDraftsListBody(mode);
  }
}

// ── Cross-draft member lists ("Без возможностей" / "Не подтверждены") ──
function _schedRenderMembersList(root, value, kind) {
  const titles = { availability: "Без возможностей", continuation: "Не подтверждены" };
  root.innerHTML = `<p class="sched-list-title">${escapeHtml(titles[kind] || "")}</p><div id="schedMembersListBody"></div>`;
  _schedRenderMembersListBody();
}

function _schedRenderMembersListBody() {
  const el = $("schedMembersListBody");
  if (!el) return;
  if (_schedState.membersLoading && !_schedState.members) { el.innerHTML = uiLoadingRows(3); return; }
  if (_schedState.membersError) { el.innerHTML = uiErrorState(_schedState.membersError, null); return; }
  const members = _schedState.members || [];
  if (!members.length) { el.innerHTML = uiEmptyState("✅", "Ничего не найдено", "По этому фильтру записей нет."); return; }
  el.innerHTML = `<div class="sched-student-list">${members.map(m => `
    <div class="sched-member-row">
      <div>
        ${_schedMemberNameHtml(m)}
        <p class="sched-member-row__tech">черновик: ${escapeHtml(m.draft_name || "")}</p>
      </div>
      <div class="sched-member-row__badges">
        ${uiStatusBadge(SCHED_CONTINUATION_LABELS[m.continuation_status] || m.continuation_status, SCHED_CONTINUATION_TONE[m.continuation_status] || "muted")}
        ${uiStatusBadge(SCHED_MATCH_LABELS[m.availability_match] || m.availability_match, SCHED_MATCH_TONE[m.availability_match] || "muted")}
      </div>
      <button class="secondary" onclick="_schedOpenDraftEditor(${m.draft_id})">Открыть черновик</button>
    </div>`).join("")}</div>`;
}

async function _schedLoadMembers(value, kind) {
  _schedState.membersLoading = true;
  _schedState.membersError = null;
  const myToken = _schedState.reqToken;
  const qp = new URLSearchParams({ limit: "100" });
  qp.set(kind, value);
  try {
    const d = await apiGet(`/api/schedule/members?${qp.toString()}`);
    if (myToken !== _schedState.reqToken) return;
    _schedState.members = d.members || [];
    _schedState.membersTotal = d.total || 0;
    _schedState.membersLoading = false;
    _schedRenderMembersListBody();
  } catch (e) {
    if (myToken !== _schedState.reqToken) return;
    _schedState.membersLoading = false;
    _schedState.membersError = e.message || String(e);
    _schedRenderMembersListBody();
  }
}

// ── Draft editor ─────────────────────────────────────────────────────
function _schedOpenDraftEditor(draftId) {
  _schedState.view = "draft-editor";
  _schedState.currentDraftId = draftId;
  _schedState.currentDraft = null;
  _schedState.editorDirty = false;
  _schedState.editorPending = {};
  _schedState.editorVersionConflict = false;
  _schedSetBackButton();
  const root = $("scheduleFoundationRoot");
  root.innerHTML = `<div id="schedEditorRoot">${uiLoadingRows(4)}</div>`;
  _schedLoadDraftDetail(draftId);
}

async function _schedLoadDraftDetail(draftId) {
  _schedState.currentDraftLoading = true;
  _schedState.currentDraftError = null;
  const myToken = _schedState.reqToken;
  try {
    const d = await apiGet(`/api/schedule/drafts/${draftId}`);
    if (myToken !== _schedState.reqToken) return;
    _schedState.currentDraft = d.draft;
    _schedState.currentDraftMembers = d.members || [];
    _schedState.currentDraftConflicts = d.conflicts;
    _schedState.currentDraftAudit = d.audit || [];
    _schedState.currentDraftSourceGroup = d.sourceGroup;
    _schedState.currentDraftLoading = false;
    _schedState.editorDirty = false;
    _schedState.editorPending = {};
    _schedRenderDraftEditor();
  } catch (e) {
    if (myToken !== _schedState.reqToken) return;
    _schedState.currentDraftLoading = false;
    _schedState.currentDraftError = e.message || String(e);
    _schedRenderDraftEditor();
  }
}

function _schedRenderDraftEditor() {
  const root = $("schedEditorRoot");
  if (!root) return;
  // Member actions (exclude/include/note/add) are explicit, immediately-
  // submitted actions, never mixed with unsaved field edits (section 11)
  // — a single choke point here guarantees the picker never stays open
  // once editorDirty becomes true, however it became true.
  if (_schedState.editorDirty && _schedState.addPickerOpen) _schedState.addPickerOpen = false;
  if (_schedState.currentDraftLoading && !_schedState.currentDraft) { root.innerHTML = uiLoadingRows(4); return; }
  if (_schedState.currentDraftError) { root.innerHTML = uiErrorState(_schedState.currentDraftError, `_schedLoadDraftDetail(${_schedState.currentDraftId})`); return; }
  const dr = _schedState.currentDraft;
  if (!dr) { root.innerHTML = uiErrorState("Черновик не найден.", null); return; }
  const p = _schedState.editorPending;
  const val = (k) => (p[k] !== undefined ? p[k] : dr[k]);
  const mutationsEnabled = !!(_schedState.status && _schedState.status.mutationsEnabled);
  const conflicts = _schedState.currentDraftConflicts || { child_conflicts: [], teacher_conflict_drafts: [] };
  const hasConflicts = conflicts.child_conflicts.length || conflicts.teacher_conflict_drafts.length;
  const archived = dr.status === "archived";

  root.innerHTML = `
    <div class="sched-detail-header">
      <button class="sched-linklike" onclick="_schedBackButtonHandler()">← Назад</button>
      <h2>${escapeHtml(dr.name || `Черновик #${dr.id}`)} ${uiStatusBadge(SCHED_DRAFT_STATUS_LABELS[dr.status] || dr.status, SCHED_DRAFT_STATUS_TONE[dr.status] || "muted")}</h2>
      ${_schedState.editorVersionConflict ? uiInlineNotice("Черновик изменён другим сотрудником. Обновите данные перед повторным сохранением.", "warning") : ""}
      ${_schedState.editorDirty ? uiInlineNotice("Есть несохранённые изменения.", "info") : ""}
    </div>
    ${hasConflicts ? `<div class="sched-conflict-banner">
      ${conflicts.child_conflicts.length ? `<p>Пересечение по ребёнку: ${conflicts.child_conflicts.map(c => escapeHtml(c.child_display_name || c.mk_user_id) + ` (черновик «${escapeHtml(c.other_draft_name || "")}»)`).join(", ")}</p>` : ""}
      ${conflicts.teacher_conflict_drafts.length ? `<p>Пересечение по преподавателю с: ${conflicts.teacher_conflict_drafts.map(c => escapeHtml(c.other_draft_name || "")).join(", ")}</p>` : ""}
    </div>` : ""}
    <div class="sched-editor">
      <label class="sched-editor-field">Название
        <input type="text" ${archived || !mutationsEnabled ? "disabled" : ""} value="${escapeHtml(val("name") || "")}" onchange="_schedEditorFieldChange('name', this.value)" />
      </label>
      <label class="sched-editor-field">Филиал
        <input type="text" ${archived || !mutationsEnabled ? "disabled" : ""} value="${escapeHtml(val("branch_name") || "")}" onchange="_schedEditorFieldChange('branch_name', this.value)" />
      </label>
      <label class="sched-editor-field">Преподаватель
        <input type="text" ${archived || !mutationsEnabled ? "disabled" : ""} value="${escapeHtml(val("teacher_name") || "")}" onchange="_schedEditorFieldChange('teacher_name', this.value)" />
      </label>
      <label class="sched-editor-field">День недели
        <select ${archived || !mutationsEnabled ? "disabled" : ""} onchange="_schedEditorFieldChange('weekday', this.value)">
          <option value="">—</option>
          ${Object.entries(SCHED_WEEKDAY_NAMES_FULL).map(([n, name]) => `<option value="${n}" ${String(val("weekday")) === n ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}
        </select>
      </label>
      <label class="sched-editor-field">Время начала (ЧЧ:ММ)
        <input type="text" placeholder="17:00" ${archived || !mutationsEnabled ? "disabled" : ""} value="${escapeHtml(val("start_time") || "")}" onchange="_schedEditorFieldChange('start_time', this.value)" />
      </label>
      <label class="sched-editor-field">Длительность (мин)
        <input type="number" min="1" ${archived || !mutationsEnabled ? "disabled" : ""} value="${escapeHtml(val("duration_minutes") || "")}" onchange="_schedEditorFieldChange('duration_minutes', this.value)" />
      </label>
      <label class="sched-editor-field">Предполагаемая дата начала
        <input type="date" ${archived || !mutationsEnabled ? "disabled" : ""} value="${escapeHtml(val("planned_start_date") || "")}" onchange="_schedEditorFieldChange('planned_start_date', this.value)" />
      </label>
    </div>
    <div class="sched-editor-actions">
      <button class="primary" ${archived || !mutationsEnabled || !_schedState.editorDirty || _schedState.editorSaving ? "disabled" : ""} onclick="_schedSaveDraftFields()">${_schedState.editorSaving ? "Сохраняем…" : "Сохранить"}</button>
      <button class="secondary" ${!_schedState.editorDirty || _schedState.editorSaving ? "disabled" : ""} onclick="_schedCancelDraftEdits()">Отмена</button>
      ${!archived && mutationsEnabled ? `
        ${dr.status !== "ready" ? `<button class="secondary" onclick="_schedSetDraftStatus('needs_review')">Требует проверки</button>` : ""}
        ${dr.status !== "ready" ? `<button class="secondary" onclick="_schedSetDraftStatus('ready')">Готово к проверке</button>` : `<button class="secondary" onclick="_schedSetDraftStatus('needs_review')">Вернуть на проверку</button>`}
        <button class="danger" onclick="_schedConfirmArchiveDraft()">Архивировать</button>
      ` : ""}
    </div>
    <p class="sched-list-title">Участники (${_schedState.currentDraftMembers.filter(m => !m.manually_excluded).length})</p>
    ${!archived && mutationsEnabled ? `<div class="sched-cta-row"><button class="secondary" ${_schedState.editorDirty || _schedState.editorSaving ? "disabled" : ""} title="${_schedState.editorDirty ? "Сначала сохраните или отмените изменения черновика" : ""}" onclick="_schedOpenAddChildPicker()">+ Добавить ребёнка</button></div>` : ""}
    <div id="schedAddChildPicker"></div>
    <div class="sched-student-list">
      ${_schedState.currentDraftMembers.map(m => `
        <div class="sched-member-row${m.manually_excluded ? " sched-member-row--excluded" : ""}">
          <div>
            ${_schedMemberNameHtml(m)}
            ${m.internal_note ? `<p class="sched-member-row__tech">${escapeHtml(m.internal_note)}</p>` : ""}
          </div>
          <div class="sched-member-row__badges">
            ${uiStatusBadge(SCHED_CONTINUATION_LABELS[m.continuation_status] || m.continuation_status, SCHED_CONTINUATION_TONE[m.continuation_status] || "muted")}
            ${uiStatusBadge(SCHED_MATCH_LABELS[m.availability_match] || m.availability_match, SCHED_MATCH_TONE[m.availability_match] || "muted")}
          </div>
          ${!archived && mutationsEnabled ? `
            <div class="sched-member-row__actions">
              ${m.manually_excluded
                ? `<button class="secondary" ${_schedState.editorDirty ? "disabled" : ""} onclick="_schedIncludeMember('${escapeHtml(m.mk_user_id)}')">Включить</button>`
                : `<button class="secondary" ${_schedState.editorDirty ? "disabled" : ""} onclick="_schedExcludeMember('${escapeHtml(m.mk_user_id)}')">Исключить</button>`}
              <button class="sched-linklike" ${_schedState.editorDirty ? "disabled" : ""} onclick="_schedEditMemberNote('${escapeHtml(m.mk_user_id)}', '${escapeHtml(m.internal_note || "")}')">Комментарий</button>
            </div>` : ""}
        </div>`).join("")}
    </div>
    <p class="sched-list-title">История изменений</p>
    <div class="sched-audit-list">
      ${_schedState.currentDraftAudit.length ? _schedState.currentDraftAudit.map(a => `
        <p class="sched-audit-row">${escapeHtml(_schedFmtDate(a.occurred_at))} · ${escapeHtml(a.actor_name || "—")} · ${escapeHtml(a.action)}${a.field ? ` (${escapeHtml(a.field)})` : ""}</p>
      `).join("") : `<p class="sched-audit-row">Пока нет изменений.</p>`}
    </div>
  `;
  if (_schedState.addPickerOpen) _schedRenderAddChildPicker();
}

function _schedEditorFieldChange(field, value) {
  const parsed = value === "" ? null : (["weekday", "duration_minutes"].includes(field) ? Number(value) : value);
  const dr = _schedState.currentDraft;
  const original = dr ? dr[field] : undefined;
  // Bugfix: only track a field as pending if it actually differs from
  // the draft's current value — otherwise touching a field and typing
  // back the same value left it in editorPending, incorrectly kept
  // "Сохранить" enabled, and would have sent a no-op change to the
  // backend (still a real field_changed audit row + version bump there,
  // since the backend can't tell "same value" from "no change" once a
  // key is present in the changes dict at all).
  const same = parsed === original || (parsed == null && original == null) || String(parsed) === String(original ?? "");
  if (same) {
    delete _schedState.editorPending[field];
  } else {
    _schedState.editorPending[field] = parsed;
  }
  _schedState.editorDirty = Object.keys(_schedState.editorPending).length > 0;
  _schedRenderDraftEditor();
}

function _schedCancelDraftEdits() {
  // Cancel: discard any unsaved changes and re-render with the draft's
  // original values (val() in _schedRenderDraftEditor falls back to
  // dr[k] once editorPending is empty) — never touches the backend.
  _schedState.editorPending = {};
  _schedState.editorDirty = false;
  _schedState.editorVersionConflict = false;
  _schedRenderDraftEditor();
}

// Bug-fix (real-data E2E finding) — every schedule mutation below uses
// _apiPostRaw (miniapp/app.js:708, pre-existing — same helper already used
// by linkClientChild/_wsOcCreateInvite), never the shared apiPost. apiPost
// does `if (!data.ok) throw new Error(...)` unconditionally, so the
// `if (!d.ok) { if (d.reason_code === "...") {...} }` branches below were
// silently unreachable dead code: apiPost had already thrown and control
// jumped straight to the outer catch (a generic toast) before `d` could
// ever be inspected. This broke both the dedicated version-conflict inline
// banner (editorVersionConflict never actually got set from a live save/
// mutation) and, more seriously, the pending-confirmation override dialog
// in _schedAddChildToDraft (uiConfirmSheet was never called at all — the
// override flow was completely unreachable). _apiPostRaw returns the raw
// {ok, reason_code, error} payload without throwing, while fetch()/
// res.json() still throw naturally for real network/transport/invalid-
// JSON failures — audited across the whole file: every OTHER apiPost
// caller (~90 call sites, payments/food/communications/admin/etc.) relies
// on try/catch around the thrown Error and never inspects .ok/.reason_code
// itself, so apiPost's own throw-on-error behavior is left completely
// unchanged for them.
async function _schedSaveDraftFields() {
  const dr = _schedState.currentDraft;
  if (!dr || _schedState.editorSaving) return;
  _schedState.editorSaving = true;
  _schedRenderDraftEditor();
  try {
    const d = await _apiPostRaw(`/api/schedule/drafts/${dr.id}/update`, { expected_version: dr.version, changes: _schedState.editorPending });
    if (!d.ok) {
      if (d.reason_code === "version_conflict") { _schedState.editorVersionConflict = true; _schedState.editorSaving = false; _schedRenderDraftEditor(); return; }
      throw new Error(d.error || "Ошибка сохранения");
    }
    _schedState.editorSaving = false;
    await _schedLoadDraftDetail(dr.id);
    setNotice("Черновик сохранён.", "success");
  } catch (e) {
    _schedState.editorSaving = false;
    setNotice(`Не удалось сохранить: ${e.message}`, "error");
    _schedRenderDraftEditor();
  }
}

async function _schedSetDraftStatus(newStatus) {
  const dr = _schedState.currentDraft;
  if (!dr) return;
  try {
    const d = await _apiPostRaw(`/api/schedule/drafts/${dr.id}/status`, { expected_version: dr.version, status: newStatus });
    if (!d.ok) {
      if (d.reason_code === "version_conflict") { _schedState.editorVersionConflict = true; _schedRenderDraftEditor(); return; }
      throw new Error(d.error || "Ошибка");
    }
    await _schedLoadDraftDetail(dr.id);
  } catch (e) {
    setNotice(`Не удалось изменить статус: ${e.message}`, "error");
  }
}

function _schedConfirmArchiveDraft() {
  const dr = _schedState.currentDraft;
  if (!dr) return;
  uiConfirmSheet({
    title: "Архивировать черновик?",
    message: "Черновик будет перенесён в архив и станет недоступен для редактирования. Это действие можно отменить только вручную через статус.",
    confirmLabel: "Архивировать", danger: true,
    onConfirm: () => _schedSetDraftStatus("archived"),
  });
}

// Member actions (exclude/include/note/add) are separate, immediately-
// submitted actions — never batched with unsaved editorPending field
// edits (section 11). Every caller below checks this first; the buttons
// that trigger them are also rendered disabled while editorDirty, so this
// is defense-in-depth against a stale/cached click, not the only guard.
function _schedMemberActionsBlockedByDirty() {
  if (_schedState.editorDirty) {
    setNotice("Сначала сохраните или отмените изменения черновика.", "error");
    return true;
  }
  return false;
}

async function _schedExcludeMember(mkUserId) {
  if (_schedMemberActionsBlockedByDirty()) return;
  const dr = _schedState.currentDraft;
  if (!dr) return;
  try {
    const d = await _apiPostRaw(`/api/schedule/drafts/${dr.id}/members/exclude`, { mk_user_id: mkUserId, expected_version: dr.version });
    if (!d.ok) {
      if (d.reason_code === "version_conflict") { _schedState.editorVersionConflict = true; _schedRenderDraftEditor(); return; }
      throw new Error(d.error || "Ошибка");
    }
    await _schedLoadDraftDetail(dr.id);
  } catch (e) { setNotice(`Не удалось исключить: ${e.message}`, "error"); }
}

async function _schedIncludeMember(mkUserId) {
  if (_schedMemberActionsBlockedByDirty()) return;
  const dr = _schedState.currentDraft;
  if (!dr) return;
  try {
    const d = await _apiPostRaw(`/api/schedule/drafts/${dr.id}/members/include`, { mk_user_id: mkUserId, expected_version: dr.version });
    if (!d.ok) {
      if (d.reason_code === "version_conflict") { _schedState.editorVersionConflict = true; _schedRenderDraftEditor(); return; }
      throw new Error(d.error || "Ошибка");
    }
    await _schedLoadDraftDetail(dr.id);
  } catch (e) { setNotice(`Не удалось включить: ${e.message}`, "error"); }
}

function _schedEditMemberNote(mkUserId, currentNote) {
  if (_schedMemberActionsBlockedByDirty()) return;
  const note = prompt("Внутренний комментарий:", currentNote || "");
  if (note === null) return;
  const dr = _schedState.currentDraft;
  if (!dr) return;
  _apiPostRaw(`/api/schedule/drafts/${dr.id}/members/note`, { mk_user_id: mkUserId, note, expected_version: dr.version })
    .then(d => {
      if (!d.ok) {
        if (d.reason_code === "version_conflict") { _schedState.editorVersionConflict = true; _schedRenderDraftEditor(); return; }
        throw new Error(d.error || "Ошибка");
      }
      return _schedLoadDraftDetail(dr.id);
    })
    .catch(e => setNotice(`Не удалось сохранить комментарий: ${e.message}`, "error"));
}

// ── ALE-10 member composition slice — "Добавить ребёнка" ────────────────
function _schedOpenAddChildPicker() {
  if (_schedMemberActionsBlockedByDirty()) return;
  _schedState.addPickerOpen = true;
  _schedState.addCandidates = null;
  _schedState.addCandidatesError = null;
  _schedState.addCandidatesRenderLimit = 30;
  _schedRenderDraftEditor();
  _schedLoadAddCandidates();
}

function _schedCloseAddChildPicker() {
  _schedState.addPickerOpen = false;
  _schedRenderDraftEditor();
}

// Bug-fix (real-data E2E finding) — a real snapshot can have far more than
// one page's worth of candidates (576 in the production copy used for
// E2E validation); GET add-candidates already supports limit/offset/total
// (server max 300/page, matching _SCHED_CHILDREN_PAGE_LIMIT), so this
// loops every page rather than fetching a single capped batch — same
// offset-loop + total-aware-stop + dedup + hard-page-cap + own-generation-
// counter pattern already established by _schedLoadChildrenPlan above.
const _SCHED_ADD_CANDIDATES_PAGE_LIMIT = 300;
const _SCHED_ADD_CANDIDATES_MAX_PAGES = 50; // 50 * 300 = 15,000 candidates hard ceiling

async function _schedLoadAddCandidates() {
  const dr = _schedState.currentDraft;
  if (!dr) return;
  const myGen = ++_schedState.addCandidatesReqGen;
  _schedState.addCandidatesLoading = true;
  _schedState.addCandidatesError = null;
  _schedRenderAddChildPicker();
  try {
    let offset = 0;
    let all = [];
    let total = 0;
    for (let page_i = 0; page_i < _SCHED_ADD_CANDIDATES_MAX_PAGES; page_i++) {
      const d = await apiGet(`/api/schedule/drafts/${dr.id}/add-candidates?limit=${_SCHED_ADD_CANDIDATES_PAGE_LIMIT}&offset=${offset}`);
      if (myGen !== _schedState.addCandidatesReqGen) return;
      const page = d.candidates || [];
      all = all.concat(page);
      total = d.total || 0;
      offset += _SCHED_ADD_CANDIDATES_PAGE_LIMIT;
      if (offset >= total || !page.length) break;
    }
    // Defensive de-dup by mk_user_id — same idiom as _schedLoadChildrenPlan
    // (a candidate must never appear twice even if draft membership shifted
    // between two page fetches of the same multi-page load).
    const seen = new Set();
    const deduped = [];
    for (const c of all) {
      if (seen.has(c.mk_user_id)) continue;
      seen.add(c.mk_user_id);
      deduped.push(c);
    }
    _schedState.addCandidates = deduped;
    _schedState.addCandidatesTotal = total;
    _schedState.addCandidatesLoading = false;
    _schedRenderAddChildPicker();
  } catch (e) {
    if (myGen !== _schedState.addCandidatesReqGen) return;
    _schedState.addCandidatesLoading = false;
    _schedState.addCandidatesError = e.message || String(e);
    _schedRenderAddChildPicker();
  }
}

function _schedAddCandidatesShowMore() {
  _schedState.addCandidatesRenderLimit = (_schedState.addCandidatesRenderLimit || 30) + 30;
  _schedRenderAddChildPicker();
}

function _schedRenderAddChildPicker() {
  const el = $("schedAddChildPicker");
  if (!el) return;
  if (!_schedState.addPickerOpen) { el.innerHTML = ""; return; }
  if (_schedState.addCandidatesLoading && !_schedState.addCandidates) {
    el.innerHTML = `<p class="sched-list-title">Добавить ребёнка</p>${uiLoadingRows(3)}`;
    return;
  }
  if (_schedState.addCandidatesError) {
    el.innerHTML = `<p class="sched-list-title">Добавить ребёнка</p>${uiErrorState(_schedState.addCandidatesError, "_schedLoadAddCandidates()")}`;
    return;
  }
  const all = _schedState.addCandidates || [];
  if (!all.length) {
    el.innerHTML = `<p class="sched-list-title">Добавить ребёнка</p>${uiEmptyState("👥", "Некого добавить", "Все дети из этого набора данных уже в черновике.")}<div class="sched-cta-row"><button class="sched-linklike" onclick="_schedCloseAddChildPicker()">Закрыть</button></div>`;
    return;
  }
  const limit = _schedState.addCandidatesRenderLimit || 30;
  const visible = all.slice(0, limit);
  const hasMore = all.length > visible.length;
  const byGroup = {};
  for (const c of visible) { (byGroup[c.candidate_group] || (byGroup[c.candidate_group] = [])).push(c); }
  el.innerHTML = `
    <p class="sched-list-title">Добавить ребёнка</p>
    <p class="ws-results-count">Показано ${visible.length} из ${all.length}</p>
    ${SCHED_ADD_CANDIDATE_GROUP_ORDER.filter(g => byGroup[g] && byGroup[g].length).map(g => `
      <p class="sched-list-title">${escapeHtml(SCHED_ADD_CANDIDATE_GROUP_LABELS[g])} (${byGroup[g].length})</p>
      <div class="sched-student-list">${byGroup[g].map(_schedAddCandidateRowHtml).join("")}</div>
    `).join("")}
    ${hasMore ? `<div class="sched-cta-row"><button class="secondary" onclick="_schedAddCandidatesShowMore()">Показать ещё</button></div>` : ""}
    <div class="sched-cta-row"><button class="sched-linklike" onclick="_schedCloseAddChildPicker()">Закрыть</button></div>
  `;
}

function _schedAddCandidateRowHtml(c) {
  const stopped = c.candidate_group === "stopped";
  const busy = _schedState.addingMemberId === c.mk_user_id;
  const historicalLine = c.historical_group_name
    ? `Прошлая группа: ${escapeHtml(c.historical_group_name)}${c.historical_weekday ? " · " + escapeHtml(SCHED_WEEKDAY_NAMES[c.historical_weekday] || "") + " " + escapeHtml(c.historical_start_time || "") : ""}`
    : "Прошлая группа не определена однозначно";
  return `
    <div class="sched-member-row">
      <div>
        ${_schedMemberNameHtml(c)}
        <p class="sched-member-row__tech">${historicalLine}</p>
      </div>
      <div class="sched-member-row__badges">
        ${uiStatusBadge(SCHED_CONTINUATION_LABELS[c.continuation_status] || c.continuation_status, SCHED_CONTINUATION_TONE[c.continuation_status] || "muted")}
        ${uiStatusBadge(SCHED_MATCH_LABELS[c.target_slot_availability_match] || c.target_slot_availability_match, SCHED_MATCH_TONE[c.target_slot_availability_match] || "muted")}
        ${uiStatusBadge(SCHED_PREVIEW_DECISION_LABELS[c.decision] || c.decision, SCHED_PREVIEW_DECISION_TONE[c.decision] || "muted")}
      </div>
      <button class="secondary" ${stopped || busy ? "disabled" : ""} onclick="_schedAddChildToDraft('${escapeHtml(c.mk_user_id)}')">${busy ? "Добавляем…" : "Добавить"}</button>
    </div>`;
}

async function _schedAddChildToDraft(mkUserId, overridePending) {
  if (_schedMemberActionsBlockedByDirty()) return;
  const dr = _schedState.currentDraft;
  if (!dr || _schedState.addingMemberId) return;
  _schedState.addingMemberId = mkUserId;
  _schedRenderAddChildPicker();
  try {
    const d = await _apiPostRaw(`/api/schedule/drafts/${dr.id}/members/add`, {
      mk_user_id: mkUserId, expected_version: dr.version, override_pending: !!overridePending,
    });
    _schedState.addingMemberId = null;
    if (!d.ok) {
      if (d.reason_code === "version_conflict") { _schedState.editorVersionConflict = true; _schedRenderDraftEditor(); return; }
      if (d.reason_code === "pending_confirmation_requires_override") {
        _schedRenderAddChildPicker();
        uiConfirmSheet({
          title: "Продолжение обучения не подтверждено",
          message: "Родитель ещё не подтвердил продолжение обучения. Всё равно добавить ребёнка в этот черновик?",
          confirmLabel: "Всё равно добавить", cancelLabel: "Отмена",
          onConfirm: () => _schedAddChildToDraft(mkUserId, true),
        });
        return;
      }
      throw new Error(d.error || "Не удалось добавить ребёнка");
    }
    await _schedLoadDraftDetail(dr.id);
    await _schedLoadAddCandidates();
    setNotice("Ребёнок добавлен в черновик.", "success");
  } catch (e) {
    _schedState.addingMemberId = null;
    setNotice(`Не удалось добавить: ${e.message}`, "error");
    _schedRenderAddChildPicker();
  }
}

